run_closed_stop_comparison:
"""Matched full closed-chain reverse-stop ramps; diagnostic only, no automatic promotion."""

import sys
from pathlib import Path
_cli_package_root = str(Path(__file__).resolve().parents[1] / "plane")
if _cli_package_root not in sys.path:
    sys.path.insert(0, _cli_package_root)
import argparse,concurrent.futures,hashlib,json,os,subprocess,sys,time
from datetime import datetime
from pathlib import Path
from wheel_legged_gym.evaluation.sequences import summarize
from wheel_legged_gym.app.completion import write_report,wake_session
ROOT=Path(__file__).resolve().parents[1]


def main():
    parser=argparse.ArgumentParser(__doc__)
    parser.add_argument('--durations',type=float,nargs='+',default=[.05,.25,1.])
    args=parser.parse_args()
    if any(d<=0 or d>10 for d in args.durations) or len(set(args.durations))!=len(args.durations):
        parser.error('Require unique ramp durations in (0,10]')
    job=ROOT/'plane/outputs'/('closed_stop_comparison_'+datetime.now().strftime('%Y%m%d_%H%M%S'));job.mkdir()
    sources={'baseline':ROOT/'plane/outputs/motion_goal_20260922_084744/accepted_basic_motion.onnx',
             'candidate':ROOT/'plane/outputs/motion_goal_20260922_111611/diagnostic_10300.onnx'}
    state={'status':'evaluating','supervisor_pid':os.getpid(),'results':[],'durations':args.durations}
    def save():
        tmp=job/'status.tmp';tmp.write_text(json.dumps(state,indent=2)+'\n');tmp.replace(job/'status.json')
    print(job,flush=True);save()
    def trial(name,policy,duration):
        tag=f'{name}_ramp{duration}';seq=job/(tag+'_sequence.json');out=job/(tag+'.json')
        sequence={'interpolation':'linear','keyframes':[{'time':t,'command':[v,0,.4]} for t,v in
            [(0,0),(2,0),(3,-2),(7,-2),(7+duration,0)]]}
        seq.write_text(json.dumps(sequence,indent=2)+'\n')
        warmup=9+duration;steps=round((warmup+20)*1000)
        sha=hashlib.sha256(policy.read_bytes()).hexdigest()
        cmd=[sys.executable,str(ROOT/'tools/probe_closed_initialization.py'),'--policy',str(policy),
             '--out',str(out),'--initialization','tree_zero','--steps',str(steps),
             '--sequence-json',str(seq),'--metrics-warmup-seconds',str(warmup),'--trace']
        if (job/'STOP').exists():return {'tag':tag,'stopped':True}
        with (job/(tag+'.log')).open('w') as log:
            child=subprocess.Popen(cmd,cwd=ROOT,stdout=log,stderr=subprocess.STDOUT)
            (job/(tag+'_process.json')).write_text(json.dumps({'pid':child.pid,'command':cmd})+'\n')
            try:
                while child.poll() is None:
                    if (job/'STOP').exists():child.terminate();child.wait();return {'tag':tag,'stopped':True}
                    time.sleep(2)
                if child.returncode:raise RuntimeError(tag+' failed process')
            finally:
                if child.poll() is None:child.terminate();child.wait()
        raw=json.loads(out.read_text());assert raw['policy_sha256']==sha
        report=summarize(raw);report.update(tag=tag,policy_sha256=sha,
            raw_sha256=hashlib.sha256(out.read_bytes()).hexdigest(),failure=raw['result']['failure'],
            completed_steps=raw['result']['completed_steps'])
        (job/(tag+'_summary.json')).write_text(json.dumps(report,indent=2)+'\n')
        return report
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            futures=[pool.submit(trial,n,p,d) for d in args.durations for n,p in sources.items()]
            for f in concurrent.futures.as_completed(futures):state['results'].append(f.result());save()
        state['status']='stopped' if (job/'STOP').exists() else 'finished_pending_review'
    except BaseException as exc:state.update(status='error',error=str(exc))
    finally:
        save();write_report(job,state)
        lines=['# 闭链后退停车对照','',f"状态：{state['status']}",'','| 案例 | 通过 | 完成步数 | 失败 |','|---|---|---:|---|']
        for r in state['results']:lines.append(f"| {r['tag']} | {r.get('passed')} | {r.get('completed_steps')} | {r.get('failure')} |")
        lines+=['','同一初始化/物理保护。候选尚未被提升；完整goal仍需高速稳态和动态验证。']
        (job/'completion_report.md').write_text('\n'.join(lines)+'\n')
        if os.environ.get('HAPI_SESSION_ID'):wake_session(job,os.environ['HAPI_SESSION_ID'])


if __name__=='__main__':main()

run_sim2sim_adaptation_pair:
"""Same-source control/treatment short training; retain explicit run provenance."""
import json,os,sys,subprocess,time,fcntl
from pathlib import Path
from datetime import datetime
ROOT=Path(__file__).resolve().parents[1]


def main():
    lock=(ROOT/'plane/outputs/sim2sim_adaptation_pair.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    job=ROOT/'plane/outputs'/('sim2sim_adaptation_'+datetime.now().strftime('%Y%m%d_%H%M%S'));job.mkdir()
    source=ROOT/'plane/logs/wheel_legged/Sep21_14-37-19_motion_goal_20260921_143444_r01_basic_motion/model_9500.pt'
    state={'status':'running','supervisor_pid':os.getpid(),'child_pid':None,'source':str(source),'completed':[],
           'scope':'User permits descendants; original9500 retained. Single-variable command timing control vs treatment.'}
    def save():
        tmp=job/'status.tmp';tmp.write_text(json.dumps(state,indent=2)+'\n');tmp.replace(job/'status.json')
    print(job,flush=True);save()
    try:
        for name,seconds in [('control',0),('switch5',5)]:
            logpath=job/(name+'.log');state['stage']=name
            before=set((ROOT/'plane/outputs').glob('motion_goal_*'))
            args=[sys.executable,str(ROOT/'tools/run_motion_goal.py'),'--recover-motion','--basic-motion',
                  '--recover-from='+str(source),'--command-switch-seconds='+str(seconds),
                  '--training-seed=23','--max-rounds=1','--high-speed-geometry-floor=.03']
            with logpath.open('w') as log:
                child=subprocess.Popen(args,cwd=ROOT,stdout=log,stderr=subprocess.STDOUT)
                state.update(command=args,child_pid=child.pid);save()
                childjob=None
                try:
                    while child.poll() is None:
                        # Child prints its absolute output directory after acquiring its training lock.
                        for line in logpath.read_text().splitlines():
                            if line.startswith(str(ROOT/'plane/outputs/motion_goal_')):
                                childjob=Path(line.strip());state['child_job']=str(childjob);save();break
                        if (job/'STOP').exists():
                            if childjob:(childjob/'STOP').touch()
                            else:child.terminate()
                        time.sleep(2)
                    if (job/'STOP').exists():raise InterruptedError('User STOP')
                    if child.returncode:raise RuntimeError(f'{name} exited {child.returncode}')
                finally:
                    if child.poll() is None:
                        if childjob:(childjob/'STOP').touch()
                        else:child.terminate()
                        child.wait()
                    state['child_pid']=None;save()
            if childjob is None:raise RuntimeError('Missing child provenance')
            result=json.loads((childjob/'status.json').read_text())
            state['completed'].append({'stage':name,'job':str(childjob),'status':result['status'],
                                       'history':result['history'],'accepted':result.get('accepted')});save()
        state['status']='training_pair_complete_pending_closed_chain_validation';save()
    except BaseException as exc:
        state.update(status='stopped' if isinstance(exc,InterruptedError) else 'error',error=str(exc));save();raise


if __name__=='__main__':main()

validate_adaptation_candidates:
"""Wait for the paired training, then validate only source-accepted ONNX candidates."""
import json,sys,os,time,subprocess,fcntl,argparse
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]


def main():
    parser=argparse.ArgumentParser(__doc__);parser.add_argument('pair',type=Path)
    parser.add_argument('--single-job',action='store_true',help='Watch one basic-motion training job instead of a pair')
    args=parser.parse_args()
    pair=args.pair.resolve();lock=(pair/'closed_validation.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    out=pair/'closed_validation_status.json'
    if out.exists():raise FileExistsError(out)
    state={'status':'waiting_for_training','supervisor_pid':os.getpid(),'child_pid':None,'results':[]}
    def save():
        tmp=out.with_suffix('.tmp');tmp.write_text(json.dumps(state,indent=2)+'\n');tmp.replace(out)
    save()
    try:
        while True:
            if (pair/'STOP').exists():raise InterruptedError('User STOP')
            training=json.loads((pair/'status.json').read_text())
            if args.single_job and (training['status'].startswith('paused_') or
                    training['status']=='motion_and_geometry_passed_pending_dynamic_validation'):
                training={'completed':[{'stage':'basic_motion','job':str(pair),
                                        'accepted':training.get('accepted')}]}
                break
            if training['status']=='training_pair_complete_pending_closed_chain_validation':break
            if training['status'] in ['error','stopped']:raise RuntimeError('Training did not finish: '+str(training.get('error')))
            os.kill(training['supervisor_pid'],0)
            time.sleep(2)
        for entry in training['completed']:
            if not entry.get('accepted'):
                state['results'].append({'stage':entry['stage'],'status':'not_run_source_acceptance_failed'});save();continue
            childjob=Path(entry['job']);policy=childjob/'accepted_basic_motion.onnx'
            if not policy.exists():raise FileNotFoundError(policy)
            with (pair/(entry['stage']+'_closed.log')).open('w') as log:
                child=subprocess.Popen(['/home/kellen/anaconda3/envs/robot/bin/python',str(ROOT/'tools/validate_closed_ramp.py'),
                    '--policy',str(policy)],cwd=ROOT,stdout=log,stderr=subprocess.STDOUT)
                state.update(status='validating',stage=entry['stage'],child_pid=child.pid);save()
                validation_job=None
                try:
                    while child.poll() is None:
                        for line in (pair/(entry['stage']+'_closed.log')).read_text().splitlines():
                            if line.startswith(str(ROOT/'plane/outputs/closed_ramp_v2_')):
                                validation_job=Path(line.strip());state['validation_job']=str(validation_job);save()
                        if (pair/'STOP').exists():
                            if validation_job:(validation_job/'STOP').touch()
                            else:child.terminate()
                        time.sleep(2)
                    if (pair/'STOP').exists():raise InterruptedError('User STOP')
                    if child.returncode:raise RuntimeError('Closed validation process failed')
                finally:
                    if child.poll() is None:
                        if validation_job:(validation_job/'STOP').touch()
                        else:child.terminate()
                        child.wait()
                    state['child_pid']=None;save()
            if not validation_job:raise RuntimeError('Missing validation provenance')
            result=json.loads((validation_job/'status.json').read_text())
            state['results'].append({'stage':entry['stage'],'policy':str(policy),'job':str(validation_job),
                                    'results':result['results'],'skipped':result['skipped']});save()
        state['status']='completed_pending_comparison';save()
    except BaseException as exc:
        state.update(status='stopped' if isinstance(exc,InterruptedError) else 'error',error=str(exc));save();raise


if __name__=='__main__':main()

validate_basic_dynamics:
"""Independent seeds: steady retention, starts/stops, spin and low-speed reversals."""

import sys
from pathlib import Path
_cli_package_root = str(Path(__file__).resolve().parents[1] / "plane")
if _cli_package_root not in sys.path:
    sys.path.insert(0, _cli_package_root)
import json,os,sys,subprocess,time,hashlib,fcntl
from pathlib import Path
from datetime import datetime
from wheel_legged_gym.evaluation.transitions import summarize
from wheel_legged_gym.evaluation.gates import gate
ROOT=Path(__file__).resolve().parents[1]
CP=ROOT/'plane/logs/wheel_legged/Sep21_14-37-19_motion_goal_20260921_143444_r01_basic_motion/model_9500.pt'


def main():
    lock=(ROOT/'plane/outputs/h3_low_speed_training.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    job=ROOT/'plane/outputs'/('basic_dynamics_'+datetime.now().strftime('%Y%m%d_%H%M%S'));job.mkdir()
    state={'status':'evaluating','supervisor_pid':os.getpid(),'child_pid':None,'completed':[],
           'checkpoint':str(CP),'sha256':hashlib.sha256(CP.read_bytes()).hexdigest()}
    env=dict(os.environ,CUDA_VISIBLE_DEVICES='0',PYTHONPATH=str(ROOT/'plane'),LD_LIBRARY_PATH=str(Path(sys.executable).parent.parent/'lib'))
    def save():
        tmp=job/'status.tmp';tmp.write_text(json.dumps(state,indent=2)+'\n');tmp.replace(job/'status.json')
    print(job,flush=True);save()
    groups={'linear':[((0,0),(v,0)) for v in [-1,1,-2,2,-4,4]]+
                     [((v,0),(0,0)) for v in [-1,1,-2,2,-4,4]],
            'spin':[((0,0),(0,w)) for w in [-3,3,-4,4]]+[((0,w),(0,0)) for w in [-3,3,-4,4]],
            'reverse':[((v,0),(-v,0)) for v in [-.5,.5,-1,1]]+
                      [((0,w),(0,-w)) for w in [-1,1]]}
    try:
        for group in ['steady']+list(groups):
            for seed in [71,89,107]:
                tag=f'{group}_seed{seed}';out=job/(tag+'.json')
                if group=='steady':
                    targets=[(0,0)]+[(s*v,0) for v in [.5,1,1.5,2,2.5,3,3.5,4] for s in [-1,1]]+[(0,s*w) for w in [.5,1,2,4] for s in [-1,1]]
                else:initials,targets=zip(*groups[group])
                cmd=[sys.executable,str(ROOT/'plane/wheel_legged_gym/scripts/evaluate_policy_comparison.py'),
                     '--checkpoint='+str(CP),'--out='+str(out),'--seed='+str(seed),'--seconds=60',
                     '--commands']+[str(v) for v,w in targets]+['--yaw-commands']+[str(w) for v,w in targets]
                if group!='steady':
                    cmd+=['--seconds=20','--warmup=10','--switch-at=5','--trace-stride=1',
                          '--initial-commands']+[str(v) for v,w in initials]+['--initial-yaw-commands']+[str(w) for v,w in initials]
                with (job/(tag+'.log')).open('w') as log:
                    child=subprocess.Popen(cmd,cwd=ROOT,env=env,stdout=log,stderr=subprocess.STDOUT)
                    state.update(operation=tag,child_pid=child.pid);save()
                    try:
                        while child.poll() is None:
                            if (job/'STOP').exists():raise InterruptedError('User STOP')
                            time.sleep(2)
                        if child.returncode:raise RuntimeError(f'{tag} exited {child.returncode}')
                    finally:
                        if child.poll() is None:child.terminate();child.wait()
                        state['child_pid']=None;save()
                d=json.loads(out.read_text())
                if d['checkpoint_sha256']!=state['sha256']:raise RuntimeError('Checkpoint changed')
                report={'steady_checks':[dict(command=r['command'],gate=gate(r),
                    geometry_passed=(r['command'][1]!=0 or max(r['metrics']['knee_mirror_m'],r['metrics']['wheel_mirror_m'])<=.03),
                    full_contact_passed=r['nonwheel_contact_full_fraction']==0) for r in d['results']]}
                if group!='steady':report['response']=summarize(d)
                (job/(tag+'_summary.json')).write_text(json.dumps(report,indent=2)+'\n')
                state['completed'].append(tag);save()
        state['status']='completed_pending_dynamic_review';save()
    except BaseException as exc:
        state.update(status='error',error=str(exc));save();raise


if __name__=='__main__':main()

validate_closed_ramp:
"""Audited ramp-and-hold validation, never changes closed-chain safety gates."""

import sys
from pathlib import Path
_cli_package_root = str(Path(__file__).resolve().parents[1] / "plane")
if _cli_package_root not in sys.path:
    sys.path.insert(0, _cli_package_root)
import json,os,sys,subprocess,time,fcntl,argparse,hashlib,threading
from wheel_legged_gym.workflows.validation_schedule import run_grid
from pathlib import Path
from datetime import datetime
ROOT=Path(__file__).resolve().parents[1]


def main():
    parser=argparse.ArgumentParser(__doc__)
    parser.add_argument('--policy',type=Path,default=ROOT/'plane/outputs/motion_goal_20260921_143444/accepted_basic_motion.onnx')
    parser.add_argument('--workers',type=int,choices=[1,2,3,4],default=1)
    args=parser.parse_args();policy=args.policy.resolve()
    policy_sha=hashlib.sha256(policy.read_bytes()).hexdigest()
    lock=(ROOT/'plane/outputs/closed_ramp.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    job=ROOT/'plane/outputs'/('closed_ramp_v2_'+datetime.now().strftime('%Y%m%d_%H%M%S'));job.mkdir()
    state={'status':'evaluating','supervisor_pid':os.getpid(),'child_pid':None,'results':[],
           'policy':str(policy),'policy_sha256':policy_sha,'workers':args.workers,'child_pids':{},
           'protocol':'2s zero hold; 10s ramp; 2s settling; 20s target measurement', 'skipped':[]}
    state_lock=threading.RLock();cancelled=threading.Event()
    def save():
        with state_lock:
            tmp=job/'status.tmp';tmp.write_text(json.dumps(state,indent=2)+'\n');tmp.replace(job/'status.json')
    def child_state(tag,pid):
        with state_lock:
            if pid is None:state['child_pids'].pop(tag,None)
            else:state['child_pids'][tag]=pid
            state['child_pid']=next(iter(state['child_pids'].values())) if len(state['child_pids'])==1 else None
            state['operation']=list(state['child_pids']);save()
    def record(result):
        with state_lock:state['results'].append(result);save()
    def skip(tag):
        with state_lock:state['skipped'].append(tag);save()
    print(job,flush=True);save()
    def evaluate(case):
            tag,v,w=case
            if (job/'STOP').exists() or cancelled.is_set():raise InterruptedError('Validation cancelled')
            out=job/(tag+'.json')
            command=[sys.executable,str(ROOT/'tools/probe_closed_initialization.py'),
                  '--policy',str(policy),
                  '--out',str(out),'--initialization','tree_zero','--steps','34000',
                  '--settle-seconds','2','--ramp-seconds','10','--metrics-warmup-seconds','14',
                  '--forward',str(v),'--yaw',str(w)]
            with (job/(tag+'.log')).open('w') as log:
                child=subprocess.Popen(command,cwd=ROOT,stdout=log,stderr=subprocess.STDOUT)
                child_state(tag,child.pid)
                try:
                    while child.poll() is None:
                        if (job/'STOP').exists() or cancelled.is_set():raise InterruptedError('Validation cancelled')
                        time.sleep(2)
                    if child.returncode:raise RuntimeError(f'{tag} failed with exit {child.returncode}')
                finally:
                    if child.poll() is None:child.terminate();child.wait()
                    child_state(tag,None)
            d=json.loads(out.read_text());r=d['result'];m=d['measurements']
            if d['policy_sha256']!=policy_sha:raise RuntimeError('Policy changed during validation')
            physical=r['passed'] and r['completed_steps']==34000
            if physical and m['samples']!=20000:raise RuntimeError('Unexpected steady sample count')
            tracking=physical and m['vx_mae']<=(.1 if v else .05) and m['yaw_mae']<=.1 and m['height_mae']<=.03
            return {'tag':tag,'command':[v,w,.4],'physical':physical,'tracking':tracking,
                'samples':m['samples'],'vx_mae':m['vx_mae'],'yaw_mae':m['yaw_mae'],
                'vx_mean':r['mean_forward_speed_m_s'] if physical else None,
                'yaw_mean':r['mean_yaw_rate_rad_s'] if physical else None,
                'max_closure':r['max_closure_residual_m'],'failure':r['failure']}
    try:
        run_grid(evaluate,record,skip,workers=args.workers,cancel=cancelled.set)
        state['status']='completed_pending_review';save()
    except BaseException as exc:
        state.update(status='error',error=str(exc));save();raise


if __name__=='__main__':main()
